extends "res://greedy_stock.gd"
## Expose the native capped debit to continuation scoring; native rollout pays it.
func score(g: GlassvowGame, c: CardInst, d: Dictionary, target: Variant, art: bool) -> float:
 var adjusted: Dictionary=d
 var debit: int=0
 for fx: Dictionary in d.get("effects",[]):
  if fx.get("kind")=="special" and fx.get("id")=="emberNova":
   debit+=mini(g.cb.embers,maxi(0,ji(fx.get("consumeEmbers",0))))
 if debit>0:
  adjusted=d.duplicate(true)
  adjusted.effects.append({"kind":"ember","n":-debit})
 return super.score(g,c,adjusted,target,art)

greedy_stock.gd.text:
extends "res://additive_policy.gd"
## Two-slope research adapter. Evaluates the same law as native execution.
## Missing floor_per preserves the published v18 action/draft procedure.
func payoff(stock: int, fx: Dictionary) -> int:
 return g_payoff(stock,fx)
static func g_payoff(stock: int, fx: Dictionary) -> int:
 var q: int=maxi(0,stock)
 var r: int=maxi(0,int(fx.get("reserve",0)))
 return int(fx.n)*maxi(0,q-r)+int(fx.get("floor_per",0))*mini(q,r)
func score(g: GlassvowGame,c: CardInst,d: Dictionary,target: Variant,art: bool) -> float:
 var effective: Dictionary=d
 var changed: bool=false
 for fx: Dictionary in d.get("effects",[]):
  if fx.get("kind")=="special" and fx.get("id") in ["phantom","emberNova"] and ji(fx.get("floor_per",0))!=0:
   changed=true;break
 if changed:
  effective=d.duplicate(true)
  var effects: Array=[]
  for fx: Dictionary in effective.effects:
   if fx.get("kind")=="special" and fx.get("id") in ["phantom","emberNova"]:
    var stock: int=maxi(0,g.cb.hand.size()-1) if fx.id=="phantom" else g.cb.embers
    effects.append({"kind":"dmg","n":g_payoff(stock,fx)})
   else:effects.append(fx)
  effective.effects=effects
 return super.score(g,c,effective,target,art)
func draft(g: GlassvowGame,d: Dictionary,id: String,acquire: bool=true) -> float:
 var value: float=super.draft(g,d,id,acquire)
 for fx: Dictionary in d.get("effects",[]):
  if fx.get("kind")=="special" and fx.get("id") in ["phantom","emberNova"] and ji(fx.get("floor_per",0))!=0:
   var f: Dictionary=features(g)
   var q: float=clampf(3.0+float(f.sight)*0.7+5.0*float(f.draw)/maxf(1,float(f.size)),2,7) if fx.id=="phantom" else expected_embers(g)
   value+=float(fx.floor_per)*minf(q,float(fx.get("reserve",0)))
 return value
func nova_spend_cost(g: GlassvowGame,spent: int) -> float:
 var defs: Array[Dictionary]=[];var any_smooth: bool=false
 for c: CardInst in g.run.player.deck:
  if c.id==&"novaflare":
   var fx: Dictionary=card_definition(g,c).effects[0]
   defs.append(fx);any_smooth=any_smooth or ji(fx.get("floor_per",0))!=0
 if defs.is_empty() or not any_smooth:return super.nova_spend_cost(g,spent)
 var stock: int=g.cb.embers;var owned: int=defs.size();var now: bool=false
 for c: CardInst in g.cb.hand:
  if c.id==&"novaflare" and g.cb.player.energy>=g.rules.eff_cost(g.run,g.cb,c):now=true
 var no_spend: int=stock;var after: int=maxi(0,stock-spent);var probability: float=1.0
 if not now:
  for c: CardInst in g.cb.exhaust:
   if c.id==&"novaflare":owned-=1
  probability=exposure_probability(g.cb.hand.size()+g.cb.draw.size()+g.cb.discard.size(),maxi(0,owned),5+si(g.cb.player.statuses,"nightsight"))
  var gain: int=si(g.cb.player.statuses,"emberflow")+1
  no_spend=mini(g.cb.ember_cap,stock+gain);after=mini(g.cb.ember_cap,maxi(0,stock-spent)+gain)
 var delta: float=0.0
 for fx: Dictionary in defs:delta+=g_payoff(no_spend,fx)-g_payoff(after,fx)
 return delta/defs.size()*probability*float(params.get("bank_discount",1.0))

additive_policy.gd.text:
extends "res://policy_buggy_v9.gd"
## A resource-scaled special enters the evaluator as its actual raw damage.
## The content and native state are untouched. Reserve=0 preserves v9 exactly.
func score(g: GlassvowGame,c: CardInst,d: Dictionary,target: Variant,art: bool) -> float:
 var effective: Dictionary=d.duplicate(true)
 var converted: Array=[]
 for fx: Dictionary in effective.get("effects",[]):
  if fx.get("kind")=="special" and fx.get("id")=="heldEmberWard":
   converted.append({"kind":"block","n":ji(fx.n)+ji(fx.per)*maxi(0,g.cb.embers-ji(fx.get("reserve",4)))})
  elif fx.get("kind")=="special" and fx.get("id")=="catalyst" and ji(fx.get("bonus",0))>0 and target!=null:
   var e: EnemyCombatant=g.cb.enemies[ji(target)];var q: int=si(e.statuses,"poison")
   converted.append({"kind":"status","who":"target","id":"poison","n":q*(ji(fx.n)-1)+ji(fx.bonus) if q>0 else 0})
  else:converted.append(fx)
 effective["effects"]=converted
 var needs_reserve: bool=false
 if not art:
  for fx: Dictionary in effective.get("effects",[]):
   if fx.get("kind")=="special" and fx.get("id") in ["phantom","emberNova"] and ji(fx.get("reserve",0))>0:
    needs_reserve=true
    break
  if needs_reserve:
   var effects: Array=[]
   for fx: Dictionary in effective.get("effects",[]):
    if fx.get("kind")=="special" and fx.get("id") in ["phantom","emberNova"] and ji(fx.get("reserve",0))>0:
     var stock: int=maxi(0,g.cb.hand.size()-1) if fx.id=="phantom" else g.cb.embers
     effects.append({"kind":"dmg","n":ji(fx.n)*maxi(0,stock-ji(fx.reserve))})
    else:effects.append(fx)
   effective["effects"]=effects
 return super.score(g,c,effective,target,art)

func draft(g: GlassvowGame,d: Dictionary,id: String,acquire: bool=true) -> float:
 var effective: Dictionary=d.duplicate(true)
 var effects: Array=[]
 for fx: Dictionary in effective.get("effects",[]):
  if fx.get("kind")=="special" and fx.get("id")=="heldEmberWard":
   effects.append({"kind":"block","n":float(fx.n)+float(fx.per)*maxf(0,expected_embers(g)-float(fx.get("reserve",4)))})
  else:effects.append(fx)
 effective["effects"]=effects
 var value: float=super.draft(g,effective,id,acquire)
 if id=="banklight" and route=="ember":value+=float(params.get("banklight_fit",12))
 for fx: Dictionary in d.get("effects",[]):
  if fx.get("kind")=="special" and fx.get("id")=="catalyst" and ji(fx.get("bonus",0))>0:
   value+=float(fx.bonus)*minf(1,float(features(g).poison)/8.0)
 return value

policy_buggy_v9.gd.text:
extends "res://policy_v8.gd"
## Research-only spending model. Falsifiable, no live RNG or hidden draw-order access.
func exposure_probability(population: int,successes: int,draws: int) -> float:
 if population<=0 or successes<=0 or draws<=0:return 0.0
 var miss: float=1.0
 for j: int in range(mini(population,draws)):
  miss*=float(maxi(0,population-successes-j))/float(population-j)
 return 1.0-miss
func nova_spend_cost(g: GlassvowGame,spent: int) -> float:
 var n: int=0;var reserve: int=0;var owned: int=0
 for c: CardInst in g.run.player.deck:
  if c.id==&"novaflare":
   var d: Dictionary=card_definition(g,c);var fx: Dictionary=d.effects[0]
   n+=ji(fx.n);reserve=ji(fx.get("reserve",0));owned+=1
 if owned==0:return spent*super.ember_value(g)
 var coefficient: float=float(n)/owned
 var currently_available: bool=false
 for c: CardInst in g.cb.hand:
  if c.id==&"novaflare" and g.cb.player.energy>=g.rules.eff_cost(g.run,g.cb,c):currently_available=true
 var stock: int=g.cb.embers
 var current_delta: float=coefficient*(maxi(0,stock-reserve)-maxi(0,stock-spent-reserve))
 if currently_available:return current_delta*float(params.get("bank_discount",1.0))
 for c: CardInst in g.cb.exhaust:
  if c.id==&"novaflare":owned-=1
 var population: int=g.cb.hand.size()+g.cb.draw.size()+g.cb.discard.size()
 var draws: int=5+si(g.cb.player.statuses,"nightsight")
 var probability: float=exposure_probability(population,maxi(0,owned),draws)
 # Explicit one-turn approximation: source emberflow and one normal Kindle.
 # Treat as a controller forecast, never as observed future game state.
 var gain: int=si(g.cb.player.statuses,"emberflow")+1
 var no_spend: int=mini(g.cb.ember_cap,stock+gain)
 var after_spend: int=mini(g.cb.ember_cap,maxi(0,stock-spent)+gain)
 var delta: float=coefficient*(maxi(0,no_spend-reserve)-maxi(0,after_spend-reserve))
 return delta*probability*float(params.get("bank_discount",1.0))
func score(g: GlassvowGame,c: CardInst,d: Dictionary,target: Variant,art: bool) -> float:
 var v: float=super.score(g,c,d,target,art)
 if params.get("bank_mode","legacy")!="current-plus-next":return v
 if copies(g,"novaflare")==0:return v
 if art:
  var spent: int=ji(g.content.arts[String(g.run.art)].get("cost",0))
  v+=spent*ember_value(g)-nova_spend_cost(g,spent)
 else:
  for fx: Dictionary in d.get("effects",[]):
   if fx.get("kind")=="special" and fx.get("id")=="emberdance":
    var f: float=pow(maxf(1,g.rules.eff_cost(g.run,g.cb,c)),0.7)
    v+=(g.cb.embers*ember_value(g)-nova_spend_cost(g,g.cb.embers))/f
 return v

policy_v8.gd.text:
extends "res://legacy_policy.gd"
## v8 research controller: public-state marginal estimates, never a P9 certificate.
## The archived v5 policy is retained verbatim as legacy_policy.gd.
var _feature_signature: String=""
var _features: Dictionary={}
func card_definition(g: GlassvowGame,c: CardInst) -> Dictionary:
 var d: Dictionary=g.content.cards[String(c.id)].duplicate(true)
 if c.up:d.merge(d.get("up",{}),true)
 return d
func features(g: GlassvowGame) -> Dictionary:
 var sig: String=str(g.content.get_instance_id())+":"
 for c: CardInst in g.run.player.deck:sig+=str(c.uid)+":"+String(c.id)+":"+str(c.up)+";"
 if sig==_feature_signature:return _features
 _feature_signature=sig
 var f: Dictionary={"size":g.run.player.deck.size(),"attack":0.0,"hits":0.0,"multi":0.0,"str":0.0,"draw":0.0,"sight":0.0,"flow":0.0,"embers":0.0,"poison":0.0,"exhaust":0.0,"powers":0.0}
 for c: CardInst in g.run.player.deck:
  var d: Dictionary=card_definition(g,c)
  if str(d.get("type",""))=="power":f.powers+=1.0
  if d.get("exhaust",false):f.exhaust+=1.0
  var hits: float=0.0
  for fx: Dictionary in d.get("effects",[]):
   var n: float=float(fx.get("n",0));var kind: String=str(fx.get("kind",""))
   if kind=="dmg":hits+=float(fx.get("times",1))
   elif kind=="special" and str(fx.get("id","")) in ["momentum","phantom","emberNova","execute","leech","devour","shatterEcho"]:hits+=1.0
   elif kind=="draw" and ji(d.get("cost",0))<=1:f.draw+=n
   elif kind=="ember":f.embers+=n
   elif kind=="status":
    var sid: String=str(fx.get("id",""))
    if sid=="str" and fx.get("who")=="self":f.str+=n
    elif sid=="nightsight":f.sight+=n
    elif sid=="emberflow":f.flow+=n
    elif sid=="poison":f.poison+=n*(1.5 if fx.get("who")=="allEnemies" else 1.0)
  if hits>0:f.attack+=1.0;f.hits+=hits;f.multi+=maxf(0,hits-1)
 _features=f
 return f
func cycle_repeats(g: GlassvowGame) -> float:
 var f: Dictionary=features(g)
 # Finite four-turn draft horizon; spent powers/exhausts shrink later cycles.
 var effective: float=maxf(7.0,float(f.size)-0.65*float(f.powers)-0.45*float(f.exhaust))
 var draws: float=5.0+minf(2.0,float(f.sight))+minf(3.0,5.0*float(f.draw)/maxf(1,float(f.size)))
 return clampf(4.0*draws/effective,1.0,4.0)
func expected_embers(g: GlassvowGame) -> float:
 var f: Dictionary=features(g)
 var producers: float=float(f.exhaust)*0.35+float(f.flow)*2.0+float(f.embers)*0.6
 return clampf(1.5+producers,1.0,8.0)
func ember_value(g: GlassvowGame) -> float:
 if route=="ember" and copies(g,"novaflare")>0:
  var raw: Dictionary=g.content.cards["novaflare"]
  var fx: Dictionary=raw.effects[0]
  return maxf(1.4,float(fx.n)*float(params.get("bank_value",1.1)))
 return 1.4 if g.run.aspect==0 else 2.8
func visible_draw_key(g: GlassvowGame) -> String:
 # Canonicalise only policy memory. No actual game resource is clamped.
 var text: String=super.visible_draw_key(g)
 var x: Array=JSON.parse_string(text)
 x[3]=minf(g.cb.player.block,maxf(30.0,2.0*incoming(g)))
 return JSON.stringify(x)
func non_damage_threat(g: GlassvowGame,e: EnemyCombatant) -> float:
 if e.hp<=0 or e.staggered or si(e.statuses,"poison")>=e.hp:return 0.0
 var mv: Dictionary=e.move();var v: float=minf(float(mv.get("heal",0)),maxi(0,e.max_hp-e.hp))*0.65
 v+=minf(12,float(mv.get("block",0)))*0.25
 for fx: Dictionary in mv.get("fx",[]):
  var n: float=float(fx.get("n",0));var who: String=str(fx.get("who",""));var sid: String=str(fx.get("id",""))
  if who=="player":
   if sid=="poison":v+=n*2.2
   elif sid in ["weak","frail","vulnerable"]:v+=n*2.5
  elif sid=="str":v+=n*2.2
 if mv.has("addCards"):v+=float(mv.addCards.get("n",0))*2.0
 return v
func score(g: GlassvowGame,c: CardInst,d: Dictionary,target: Variant,art: bool) -> float:
 var value: float=super.score(g,c,d,target,art)
 var cost_factor: float=1.0 if art else pow(maxf(1,g.rules.eff_cost(g.run,g.cb,c)),0.7)
 var remaining_energy: int=g.cb.player.energy if art else g.cb.player.energy-g.rules.eff_cost(g.run,g.cb,c)
 for fx: Dictionary in d.get("effects",[]):
  var n: float=float(fx.get("n",0))
  if fx.get("kind")=="draw":
   var usable: float=4.0*(1.25 if route in ["hand","cycle"] else 1.0)*clampf(remaining_energy/1.5,0,1)
   value+=(usable-draw_value(g))*minf(n,11-g.cb.hand.size())/cost_factor
  if fx.get("kind")=="status" and fx.get("who")=="self" and fx.get("id")=="str":
   var hits: float=0
   for h: CardInst in g.cb.hand:
    if c!=null and h.uid==c.uid:continue
    for hfx: Dictionary in g.rules.card_data(h).get("effects",[]):
     if hfx.get("kind")=="dmg":hits+=float(hfx.get("times",1))
   var f: Dictionary=features(g)
   var future: float=clampf(2.0*float(f.hits)/maxf(1,float(f.attack)),2.0,8.0)
   value+=n*(minf(hits,6)+future-(7.0 if route=="fervor" else 4.5))/cost_factor
  if fx.get("kind")=="special" and fx.get("id")=="momentum":
   var remaining: float=clampf(cycle_repeats(g)-0.45*maxi(0,g.cb.turn-1),0,3)
   value+=float(fx.get("grow",0))*(remaining-minf(2,10.0/maxi(5,g.run.player.deck.size())))/cost_factor
  if fx.get("kind")=="special" and fx.get("id") in ["phantom","emberNova"] and target!=null:
   var stock: int=maxi(0,g.cb.hand.size()-1) if fx.id=="phantom" else g.cb.embers
   var reserve: int=ji(fx.get("reserve",0))
   if reserve>0:
    var e: EnemyCombatant=g.cb.enemies[ji(target)]
    var old_loss: float=maxf(0,attack_hit(g,e,int(n)*stock)-e.block)
    var new_loss: float=maxf(0,attack_hit(g,e,int(n)*maxi(0,stock-reserve))-e.block)
    value+=(minf(new_loss,e.hp)-minf(old_loss,e.hp))/cost_factor
    if old_loss>=e.hp and new_loss<e.hp:value-=(threat(g,e)*float(params.get("life",2.3))+2)/cost_factor
 if not art and si(g.cb.player.statuses,"barricade")>0:
  var pv_block: Variant=g.rules.preview_play(g.cb,c,target,g.run)
  var b: float=float(pv_block.get("block",0)) if typeof(pv_block)==TYPE_DICTIONARY else 0.0
  var unblocked: float=maxf(0,incoming(g)-g.cb.player.block)
  var carry_room: float=maxf(0,maxf(30,2*incoming(g))-maxf(g.cb.player.block,incoming(g)))
