func threat(g: GlassvowGame,e: EnemyCombatant) -> float:
 if e.hp<=0 or e.staggered or si(e.statuses,"poison")>=e.hp:return 0.0
 var pv: Variant=g.rules.preview_enemy_dmg(g.cb,e,g.run)
